import React, { useContext } from "react";
import AuthContext from "../context/AuthContext";

const JWTDashboard = () => {
  const { user } = useContext(AuthContext); // Get logged-in user data

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white shadow-lg rounded-2xl p-6 w-96 text-center">
        <h1 className="text-3xl font-bold text-gray-800">Dashboard</h1>
        <p className="mt-4 text-lg text-gray-600">Welcome, <span className="font-semibold text-blue-600">{user?.name || "User"}</span>!</p>
      </div>
    </div>
  );
};

export default JWTDashboard;
